using System;
using System.Linq;
using System.Collections.Generic;
using System.Globalization;
using System.Text.RegularExpressions;
using System.Diagnostics;
using SolidWorks.Interop.sldworks;
using SolidWorks.Interop.swconst;

partial class Worker {
 static bool ParamFinite(double v){return !double.IsNaN(v)&&!double.IsInfinity(v);}
 static string ParamName(string s){var p=s.Split('@');return p.Length>2?p[0]+"@"+p[1]:s;}
 static string ParamLhs(string s){var m=Regex.Match(s,"^\\s*\"([^\"]+)\"\\s*=");return m.Success?m.Groups[1].Value:null;}
 static void ParamIdentifier(string s,bool dimension){if(string.IsNullOrWhiteSpace(s)||s.IndexOfAny(new[]{'"','\r','\n','='})>=0||(dimension?s.Split('@').Length!=2||s.Split('@').Any(string.IsNullOrWhiteSpace):s.Contains("@")))throw new Exception("Nombre de par\u00e1metro no v\u00e1lido");}
 static int ParamIndex(IEquationMgr m,string name){int found=-1;for(int i=0;i<m.GetCount();i++)if(string.Equals(ParamName(ParamLhs(m.get_Equation(i))??""),name,StringComparison.OrdinalIgnoreCase)){if(found>=0)throw new Exception("Varias ecuaciones controlan "+name);found=i;}return found;}
 static double ParamValue(IEquationMgr m,int i){double v=m.get_Value(i);int status=m.Status;if(status!=i||!ParamFinite(v))throw new Exception("No se pudo evaluar la ecuaci\u00f3n "+i+" (Status="+status+")");return v;}
 static void ParamEvaluate(IModelDoc2 d,IEquationMgr m){m.EvaluateAll();if(!d.ForceRebuild3(false))throw new Exception("Fall\u00f3 la reconstrucci\u00f3n");for(int i=0;i<m.GetCount();i++)ParamValue(m,i);var health=Health(d);var problems=new List<string>();foreach(var kv in HealthMap(health,"feature_errors")){var error=(Dictionary<string,object>)kv.Value;if(!Convert.ToBoolean(error["warning"]))problems.Add(kv.Key+": "+error["code"]);}foreach(var kv in HealthMap(health,"bad_sketches"))problems.Add(kv.Key+": croquis inv\u00e1lido "+kv.Value);if(Convert.ToInt32(health["whats_wrong"])!=0)problems.Add("GetWhatsWrong: "+health["whats_wrong"]);if(problems.Count>0)throw new Exception(string.Join("; ",problems));}
 static double ParamToSI(IModelDoc2 d,IEquationMgr m,IDimension dim,double evaluated){if(dim.GetType()!=2)return ((IUserUnit)d.GetUserUnit(0)).ConvertDoubleToSystemValue(evaluated);if(m.AngularEquationUnits==(int)swAngularEquationUnits_e.swAngularEquationUnitsDegrees)return evaluated*Math.PI/180;if(m.AngularEquationUnits==(int)swAngularEquationUnits_e.swAngularEquationUnitsRadians)return evaluated;throw new Exception("Unidades angulares de ecuaci\u00f3n desconocidas");}
 static object ParamList(IModelDoc2 d,IEquationMgr m){var globals=new List<object>();var rows=new List<object>();int initialStatus=m.Status;for(int i=0;i<m.GetCount();i++){string text=m.get_Equation(i);int textStatus=m.Status;double value=m.get_Value(i);int status=m.Status;bool global=m.get_GlobalVariable(i);object v=ParamFinite(value)?(object)value:null;rows.Add(new{index=i,text=text,value=v,is_global=global,status=status,text_status=textStatus,disabled=m.get_Disabled(i)});if(global)globals.Add(new{name=ParamLhs(text),value=v,expression=text.Substring(text.IndexOf('=')+1).Trim()});}return new{globals=globals,equations=rows,status=m.Status,status_before_reads=initialStatus,document_units=d.GetUnits(),length_unit=((IUserUnit)d.GetUserUnit(0)).GetFullUnitName(false),note="Variables globales sin unidades. Las cotas lineales se eval\u00faan en las unidades del documento (GetUnits); los \u00e1ngulos usan AngularEquationUnits. Status indica el resultado de la \u00faltima lectura indexada, no un diagn\u00f3stico completo."};}
 static int ParamWrite(IModelDoc2 d,IEquationMgr m,int i,string text){if(i>=0){m.set_Equation(i,text);if(m.Status!=i)throw new Exception("No se pudo reemplazar la ecuaci\u00f3n "+i);return i;}int added=d.GetConfigurationCount()>1?m.Add3(-1,text,false,(int)swInConfigurationOpts_e.swAllConfiguration,null):m.Add2(-1,text,false);if(added<0)throw new Exception("SolidWorks rechaz\u00f3 la ecuaci\u00f3n: "+text);// SW 2026 (tested): from the 2nd equation on, Add2 leaves the new one Disabled; enable it explicitly
  string lhs=ParamLhs(text);for(int k=0;k<m.GetCount();k++)if(string.Equals(ParamLhs(m.get_Equation(k)),lhs,StringComparison.OrdinalIgnoreCase)&&m.get_Disabled(k))try{m.set_Disabled(k,false);}catch{}return added;}
 static void ParamDelete(IEquationMgr m,int i){int count=m.GetCount();if(m.Delete(i)<0||m.GetCount()!=count-1)throw new Exception("No se pudo borrar la ecuaci\u00f3n "+i);}
 static object Parameters(Dictionary<string,object>a,IModelDoc2 d){
  var m=(IEquationMgr)d.GetEquationMgr();if(m==null)throw new Exception("Gestor de ecuaciones no disponible");string action=Str(a,"action");if(action=="list")return ParamList(d,m);
  if(m.LinkToFile)throw new Exception("Desvincula el archivo externo de ecuaciones antes de editar par\u00e1metros");
  if(action=="set_global"||action=="delete_global"){
   string name=Str(a,"name");ParamIdentifier(name,false);int i=ParamIndex(m,name);if(i>=0&&!m.get_GlobalVariable(i))throw new Exception("El nombre pertenece a una cota");
   if(action=="delete_global"){if(i<0)throw new Exception("Variable global inexistente: "+name);var uses=new List<string>();for(int j=0;j<m.GetCount();j++){string text=m.get_Equation(j);if(j!=i&&Regex.Matches(text.Substring(text.IndexOf('=')+1),"\"([^\"]+)\"").Cast<Match>().Any(x=>string.Equals(x.Groups[1].Value,name,StringComparison.OrdinalIgnoreCase)))uses.Add(j+": "+text);}if(uses.Count>0)throw new Exception("La variable "+name+" se usa en: "+string.Join("; ",uses));ParamDelete(m,i);ParamEvaluate(d,m);if(ParamIndex(m,name)>=0)throw new Exception("La variable no se elimin\u00f3");}
   else{double value=Num(a,"value");if(!ParamFinite(value))throw new Exception("Valor no finito");i=ParamWrite(d,m,i,"\""+name+"\" = "+value.ToString("R",CultureInfo.InvariantCulture));ParamEvaluate(d,m);i=ParamIndex(m,name);if(i<0||!m.get_GlobalVariable(i)||Math.Abs(ParamValue(m,i)-value)>Math.Max(1e-12,Math.Abs(value)*1e-10)){var dbg=new List<string>();for(int j=0;j<m.GetCount();j++){double vv=m.get_Value(j);int stj=m.Status;dbg.Add(j+":"+m.get_Equation(j)+"="+vv+" g="+m.get_GlobalVariable(j)+" st="+stj+" dis="+m.get_Disabled(j));}throw new Exception("La variable no conserv\u00f3 su valor (i="+i+"; "+string.Join(" | ",dbg)+")");}}
   return ParamList(d,m);
  }
  if(action!="link"&&action!="unlink")throw new Exception("Acci\u00f3n desconocida: "+action);
  string dimension=Str(a,"dimension");ParamIdentifier(dimension,true);var dim=d.Parameter(dimension) as IDimension;if(dim==null)throw new Exception("Cota inexistente: "+dimension);int index=ParamIndex(m,dimension);double original=dim.SystemValue;
  if(action=="unlink"){if(index<0)throw new Exception("La cota no tiene ecuaci\u00f3n");string[] configs=Items(d.GetConfigurationNames()).Select(Convert.ToString).ToArray();double[] before=FlexValues(dim,configs);ParamDelete(m,index);ParamEvaluate(d,m);double[] after=FlexValues(dim,configs);if(ParamIndex(m,dimension)>=0||Math.Abs(dim.SystemValue-original)>1e-12||before.Where((v,j)=>Math.Abs(v-after[j])>1e-12).Any())throw new Exception("La cota no conserv\u00f3 su valor al desvincular");return new{dimension=dimension,value_si=dim.SystemValue,parameters=ParamList(d,m)};}
  string expression=Str(a,"expression");if(string.IsNullOrWhiteSpace(expression)||expression.IndexOfAny(new[]{'\r','\n'})>=0)throw new Exception("Expresi\u00f3n no v\u00e1lida");
  string previous=index<0?null:m.get_Equation(index);int countBefore=m.GetCount();int added=-1;
  try{added=ParamWrite(d,m,index,"\""+dimension+"\" = "+expression);ParamEvaluate(d,m);int actual=ParamIndex(m,dimension);if(actual<0)throw new Exception("Ecuaci\u00f3n ausente");double evaluated=ParamValue(m,actual);double expected=ParamToSI(d,m,dim,evaluated);if(!ParamFinite(expected)||Math.Abs(dim.SystemValue-expected)>Math.Max(1e-12,Math.Abs(expected)*1e-8))throw new Exception("La cota no coincide con el valor evaluado en las unidades del documento");return new{dimension=dimension,expression=expression,evaluated=evaluated,value_si=dim.SystemValue,document_units=d.GetUnits(),parameters=ParamList(d,m)};}
  catch(Exception failure){try{if(previous!=null){m.set_Equation(index,previous);if(m.get_Equation(index)!=previous)throw new Exception("Texto anterior no restaurado");}else if(m.GetCount()>countBefore){int remove=added>=0?added:ParamIndex(m,dimension);if(remove<0)throw new Exception("No se localiz\u00f3 la ecuaci\u00f3n agregada");ParamDelete(m,remove);}m.EvaluateAll();d.ForceRebuild3(false);}catch(Exception cleanup){throw new Exception(failure.Message+"; restauraci\u00f3n local fallida: "+cleanup.Message,failure);}throw;}
 }

 sealed class FlexDimension {public string Name,Feature;public double Original;public double[] ConfigValues;public bool Angular;public IDimension Dim;}
 sealed class FlexState {public Dictionary<string,int> Errors=new Dictionary<string,int>();public Dictionary<string,int> Sketches=new Dictionary<string,int>();public int Bodies;public double Volume;}
 sealed class FlexTrial {public bool ok;public List<object> errors=new List<object>();public int? bodies;public double? volume_mm3;}
 static FlexState FlexRead(IModelDoc2 d){var s=new FlexState();foreach(var f in AllFeatures(d)){bool warning;int code=f.GetErrorCode2(out warning);if(code!=0&&!warning)s.Errors[f.Name]=code;var sk=f.GetSpecificFeature2() as ISketch;if(sk!=null&&!f.IsSuppressed())s.Sketches[f.Name]=sk.GetConstrainedStatus();}s.Bodies=((object[])((IPartDoc)d).GetBodies2(0,false)??new object[0]).Length;if(s.Bodies>0){var mp=(IMassProperty2)d.Extension.CreateMassProperty2();if(mp==null)throw new Exception("No se pudo medir volumen");mp.UseSystemUnits=true;mp.AccuracyLevel=2;mp.IncludeHiddenBodiesOrComponents=true;if(!mp.Recalculate())throw new Exception("No se pudo recalcular volumen");s.Volume=mp.Volume*1e9;if(!ParamFinite(s.Volume))throw new Exception("Volumen no finito");}return s;}
 static List<object> FlexErrors(FlexState baseline,FlexState now){var errors=new List<object>();foreach(var kv in now.Errors)if(!baseline.Errors.ContainsKey(kv.Key)||baseline.Errors[kv.Key]!=kv.Value)errors.Add(new{name=kv.Key,code=kv.Value,kind="feature"});foreach(var kv in now.Sketches){int old;bool had=baseline.Sketches.TryGetValue(kv.Key,out old);if(kv.Value>=4&&kv.Value<=6||(had&&old==3&&kv.Value!=3))errors.Add(new{name=kv.Key,code=kv.Value,kind="sketch"});}foreach(var kv in baseline.Sketches)if(!now.Sketches.ContainsKey(kv.Key)&&kv.Value==3)errors.Add(new{name=kv.Key,code=-1,kind="sketch_missing"});if(now.Bodies!=baseline.Bodies)errors.Add(new{name="bodies",code=now.Bodies,kind="body_count_changed"});return errors;}
 static double[] FlexValues(IDimension dim,string[] configs){var values=Items(dim.GetSystemValue3(3,configs)).Select(Convert.ToDouble).ToArray();if(values.Length!=configs.Length||values.Any(v=>!ParamFinite(v)))throw new Exception("No se pudieron leer todas las configuraciones de "+dim.FullName);return values;}
 static string[] FlexConfigs;
 static void FlexRestore(IModelDoc2 d,FlexDimension x,string[] configs){if(configs.Length<=1){if(x.Dim.SetSystemValue3(x.ConfigValues[0],1,null)!=0)throw new Exception("No se pudo restaurar "+x.Name);}else for(int i=0;i<configs.Length;i++)if(x.Dim.SetSystemValue3(x.ConfigValues[i],3,new[]{configs[i]})!=0)throw new Exception("No se pudo restaurar "+x.Name+" en "+configs[i]);if(!d.ForceRebuild3(false))throw new Exception("Fall\u00f3 la reconstrucci\u00f3n al restaurar "+x.Name);var now=FlexValues(x.Dim,configs);for(int i=0;i<now.Length;i++)if(Math.Abs(now[i]-x.ConfigValues[i])>1e-12)throw new Exception("Restauraci\u00f3n inexacta: "+x.Name);}
 static FlexTrial FlexTry(IModelDoc2 d,FlexDimension x,double value,FlexState baseline){var r=new FlexTrial();try{if(!ParamFinite(value)||(!x.Angular&&value<0))throw new Exception("Valor de prueba no v\u00e1lido");int status=x.ConfigValues.Length<=1?x.Dim.SetSystemValue3(value,1,null):x.Dim.SetSystemValue3(value,3,FlexConfigs);bool rebuilt=d.ForceRebuild3(false);var now=FlexRead(d);r.bodies=now.Bodies;r.volume_mm3=now.Volume;r.errors=FlexErrors(baseline,now);if(!rebuilt)r.errors.Add(new{name=x.Name,code=-1,kind="rebuild_failed"});if(status!=0)r.errors.Add(new{name=x.Name,code=status,kind="assignment"});if(Math.Abs(x.Dim.SystemValue-value)>1e-12)r.errors.Add(new{name=x.Name,code=-1,kind="value_not_retained"});r.ok=r.errors.Count==0;}catch(Exception e){r.errors.Add(new{name=x.Name,code=-1,kind="exception",message=e.Message});r.ok=false;}return r;}
 static object PartFlex(Dictionary<string,object>a,IModelDoc2 d){
  var timer=Stopwatch.StartNew();double pct=a.ContainsKey("pct")?Num(a,"pct"):0.05;double delta=a.ContainsKey("delta_mm")?Num(a,"delta_mm")/1000:0;int max=a.ContainsKey("max_dimensions")?Convert.ToInt32(a["max_dimensions"]):60;if(!ParamFinite(pct)||pct<=0||pct>=1||!ParamFinite(delta)||delta<0||max<1||max>500||(a.ContainsKey("delta_mm")&&delta==0))throw new Exception("L\u00edmites de prueba no v\u00e1lidos");
  if(!d.ForceRebuild3(false))throw new Exception("Initial rebuild failed");var baseline=FlexRead(d);if(baseline.Errors.Count>0||baseline.Sketches.Values.Any(v=>v>=4&&v<=6)||baseline.Bodies==0)throw new Exception("La pieza inicial tiene errores o no tiene cuerpos");
  string[] configs=Items(d.GetConfigurationNames()).Select(Convert.ToString).ToArray();FlexConfigs=configs;var dimensions=new Dictionary<string,FlexDimension>(StringComparer.OrdinalIgnoreCase);
  foreach(var f in AllFeatures(d)){if(f.IsSuppressed())continue;var display=f.GetFirstDisplayDimension() as IDisplayDimension;while(display!=null){var dim=display.GetDimension2(0) as IDimension;if(dim!=null){string name=ParamName(dim.FullName);if(!dimensions.ContainsKey(name))dimensions[name]=new FlexDimension{Name=name,Feature=f.Name,Original=dim.SystemValue,Angular=display.GetType()==3||display.GetType()==16||dim.GetType()==2,Dim=dim};}display=f.GetNextDisplayDimension(display) as IDisplayDimension;}}
  var selected=new List<FlexDimension>();if(a.ContainsKey("dimensions")){foreach(string name in Items(a["dimensions"]).Select(Convert.ToString)){ParamIdentifier(name,true);FlexDimension x;if(!dimensions.TryGetValue(name,out x)){var dim=d.Parameter(name) as IDimension;if(dim==null)throw new Exception("Cota inexistente: "+name);x=new FlexDimension{Name=name,Feature=name.Split('@')[1],Original=dim.SystemValue,Angular=dim.GetType()==2,Dim=dim};dimensions[name]=x;}selected.Add(x);}if(selected.Count>max)throw new Exception("dimensions excede max_dimensions");}else selected=dimensions.Values.Take(max).ToList();
  // Snapshot every discovered dimension, including equation/reference dimensions, before any perturbation.
  foreach(var x in dimensions.Values){if(!ParamFinite(x.Original))throw new Exception("Cota no finita: "+x.Name);x.ConfigValues=FlexValues(x.Dim,configs);}
  var m=(IEquationMgr)d.GetEquationMgr();if(m==null)throw new Exception("Equation manager unavailable");var rows=new List<object>();var fragile=new List<string>();int flexible=0;
  foreach(var x in selected){string verdict;FlexTrial plus=null,minus=null;if(ParamIndex(m,x.Name)>=0)verdict="controlada por ecuaci\u00f3n";else if(x.Dim.ReadOnly||x.Dim.DrivenState==(int)swDimensionDrivenState_e.swDimensionDriven)verdict="no editable ("+(x.Dim.ReadOnly?"solo lectura":"conducida")+")";else{double step=x.Angular||delta==0?x.Original*pct:delta;if(step==0)verdict="no editable";else{try{plus=FlexTry(d,x,x.Original+step,baseline);}finally{FlexRestore(d,x,configs);}FlexVerify(d,dimensions.Values,configs,baseline);try{minus=FlexTry(d,x,x.Original-step,baseline);}finally{FlexRestore(d,x,configs);}FlexVerify(d,dimensions.Values,configs,baseline);verdict=plus.ok?(minus.ok?"flexible":"se rompe al bajar"):(minus.ok?"se rompe al subir":"se rompe");if(plus.ok&&minus.ok)flexible++;else fragile.Add(x.Name);}}rows.Add(new{name=x.Name,feature=x.Feature,value_mm_or_deg=x.Angular?x.Original*180/Math.PI:x.Original*1000,plus=plus,minus=minus,verdict=verdict});}
  FlexVerify(d,dimensions.Values,configs,baseline);timer.Stop();return new{dimensions=rows,summary=new{total=rows.Count,flexibles=flexible,fragiles=fragile,time_ms=timer.ElapsedMilliseconds,available=dimensions.Count,truncated=!a.ContainsKey("dimensions")&&dimensions.Count>max},initial=new{bodies=baseline.Bodies,volume_mm3=baseline.Volume},restored=true,configuration=d.ConfigurationManager.ActiveConfiguration.Name,note="Pruebas en todas las configuraciones; reconstrucci\u00f3n y geometr\u00eda comprobadas en la activa. Valores originales verificados en todas las configuraciones. No guarda."};
 }
 static void FlexVerify(IModelDoc2 d,IEnumerable<FlexDimension> dimensions,string[] configs,FlexState baseline){foreach(var x in dimensions){var now=FlexValues(x.Dim,configs);for(int i=0;i<now.Length;i++)if(Math.Abs(now[i]-x.ConfigValues[i])>1e-12)throw new Exception("No se restaur\u00f3 exactamente "+x.Name+" en "+configs[i]);}var state=FlexRead(d);if(state.Errors.Count>0||FlexErrors(baseline,state).Count>0||Math.Abs(state.Volume-baseline.Volume)>Math.Abs(baseline.Volume)*1e-6)throw new Exception("La pieza no recuper\u00f3 su volumen, cuerpos o estado inicial");}
 static bool TryParametric(string op,Dictionary<string,object>a,IModelDoc2 doc,out object extra){extra=null;if(op!="parameters"&&op!="part_flex")return false;if(doc.GetType()!=1)throw new Exception("Se requiere una pieza gestionada");if(Flag(a,"keep_broken"))throw new Exception("keep_broken no se admite en operaciones parametricas");if(recoveryPending.Contains(doc.GetPathName())&&!(op=="parameters"&&Str(a,"action")=="list"))throw new Exception("Restauracion pendiente: no se permite editar parametros");extra=op=="parameters"?Parameters(a,doc):PartFlex(a,doc);return true;}
}
